#!/bin/sh
# Create .env for docker compose with fresh random secrets.
# SIMULATED / PAPER ONLY. The values are written to the file and never
# printed. Refuses to overwrite an existing .env.
set -eu
cd "$(dirname "$0")/.."
out="${1:-.env}"
if [ -e "$out" ]; then
	echo "gen-env: $out already exists; delete it first if you want new secrets" >&2
	exit 1
fi
command -v openssl >/dev/null 2>&1 || { echo "gen-env: openssl is required" >&2; exit 1; }
rnd() { openssl rand -hex 24; }
trader="$(rnd)"; viewer="$(rnd)"; operator="$(rnd)"

umask 077
cat > "$out" <<ENV
# Generated by scripts/gen-env.sh. SIMULATED / PAPER ONLY. Do not commit.
POSTGRES_PASSWORD=$(rnd)
OMS_BROKER_API_KEY=$(rnd)
OMS_BROKER_WEBHOOK_SECRET=$(rnd)
OMS_API_KEYS='[{"principal":"alice","role":"trader","accounts":["ACC-1","ACC-2"],"token":"$trader"},{"principal":"vera","role":"viewer","accounts":["ACC-1"],"token":"$viewer"},{"principal":"olivia","role":"operator","accounts":["*"],"token":"$operator"}]'
OMS_URL=http://127.0.0.1:8080
BROKER_URL=http://127.0.0.1:9090
TRADER_TOKEN=$trader
VIEWER_TOKEN=$viewer
OPERATOR_TOKEN=$operator
ENV
echo "gen-env: wrote $out (mode 600) with fresh random secrets"
